    Capture<Event> eventCapture = newCapture();
    send.eventAdmin.sendEvent(capture(eventCapture));
    expectLastCall();
    replay(send.eventAdmin);
    send.topic = "myTopic";
    send.properties = Arrays.asList("a=b");
    send.execute();
    verify(send.eventAdmin);
