        if (clause.getName().equals("mvn:org.apache.karaf.admin/org.apache.karaf.admin.core/2.3.0.redhat-61033X")) {
            karafAdminCore = clause;
        }
    }
    assertNotNull("Missing admin.command bundle override", karafAdminCommand);
