public void parserTest() throws Exception {
    Map parts = new HashMap();
    String uri = Parser.pathToMaven(PATH_WITH_CLASSIFIER, parts);
    Assert.assertEquals("mvn:org.apache.karaf/test/1.0-SNAPSHOT/xml/feature", uri);
